import { formatdisplayDate } from "@/JsonFiles/DateFormate.js";
export default {
  props: {
    assetdisplay: Boolean,
    assetitems: Object
  },
  data() {
    return {
      organization_currency: ""
    };
  },
  watch: {
    assetdisplay: {
      async handler() {
        if (this.assetdisplay == true) {
          this.organization_currency = this.$store.getters.GetUserObj.organization.organization_currency == undefined ? "" : this.$store.getters.GetUserObj.organization.organization_currency;
          // console.log(this.assetitems);
        }
      },
      immediate: true
    }
  },
  methods: {
    formate_date(value) {
      if (value == "N/A" || !value || value == null || value == undefined) {
        return value == "N/A" ? value : "-";
      }
      var data = formatdisplayDate(value);
      return data;
    },
    close_dialog() {
      this.$emit("clicked", 0);
    }
  }
};
